// src/api/LogsApi.js
import { get, post, del } from './HttpClient';

function toQuery(params = {}) {
  const q = new URLSearchParams();
  Object.entries(params).forEach(([k, v]) => {
    if (v === undefined || v === null || v === '') return;
    q.append(k, String(v));
  });
  const s = q.toString();
  return s ? `?${s}` : '';
}

/** ✅ 기존 유지: GET /logs/recent?limit=50 */
export function fetchRecentLogs(limit = 50) {
  return get(`/logs/recent?limit=${limit}`);
}

/**
 * 🆕 명세: GET /logs?page&size&from&to&keyword&aiLabel&eventType&sort
 * - 백엔드가 아직 없으면 useLogs에서 fetchRecentLogs로 fallback됨
 */
export function fetchLogs({
  page = 1,
  size = 50,
  from,
  to,
  keyword,
  aiLabel,
  eventType,
  sort,
} = {}) {
  return get(
    `/logs${toQuery({
      page,
      size,
      from,
      to,
      keyword,
      aiLabel,
      eventType,
      sort,
    })}`
  );
}

/** 🆕 명세: GET /logs/{id} */
export function fetchLogById(id) {
  return get(`/logs/${id}`);
}

/**
 * 🆕 명세: POST /logs/export
 * Body: { format:"CSV"|"JSON", ids:[...], filters:{...} }
 * 응답: 백엔드 구현에 따라
 *  - {downloadUrl:"..."} 또는
 *  - CSV 문자열 / JSON 객체/문자열 등이 올 수 있음
 */
export function exportLogs({ format = 'CSV', ids = [], filters = {} } = {}) {
  return post('/logs/export', { format, ids, filters });
}

/** 🆕 명세: DELETE /logs/{id} */
export function deleteLog(id) {
  return del(`/logs/${id}`);
}

/** 🆕 명세: POST /logs/delete  Body: { ids:[...] } */
export function deleteLogs(ids = []) {
  return post('/logs/delete', { ids });
}
